async function openSources(refs,index=0){const d=$('sources');sourceVersion++;d._refs=refs;d._index=index;d._page=Number(refs[index].page)||1;d._zoom=1;d.innerHTML=`<div class="row between"><h2 id="source-title" style="margin:0">Fuentes</h2>${button('Cerrar','close-sources')}</div><div class="toolbar"><label>Documento<select id="source-book">${refs.map((r,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Página PDF<input id="source-page" type="number" min="1" value="${d._page}" style="width:105px"></label><div class="row">${button('←','source-prev')}${button('→','source-next')}${button('−','source-zoom-out')}${button('+','source-zoom-in')}</div></div><p id="source-info" class="meta" role="status"></p><div id="pdf-viewer" class="viewer"><p style="padding:24px">Abriendo documento…</p></div><div id="source-quotes" class="sourcequotes"></div>`;if(!d.open)d.showModal();$('source-book').onchange=e=>openSources(refs,+e.target.value);$('source-page').onchange=e=>{d._page=Math.max(1,Number(e.target.value)||1);renderPDF()};renderPDF()}
