function questionRefs(q,graded){const ans=q.kind==='mc'?clean(q.o?.[q.k]??q.answer):clean(q.answer||'');const aq=ans&&ans.length>=8&&ans.length<=160?[ans]:[];return (q.refs||[]).map(r=>graded?{...r,aq}:{...r,hidden:true})}
