 if(!state){let index=kind==='question'?ord[0]:refs.findIndex(r=>r.key===U.bookKey&&(r.exact||r.quotes?.length));if(index<0)index=0;state={index,page:refs[index].page||1,zoom:1};bookStates.set(context,state)}
